def slow(gas, cost):               # brute force: try every start, O(N^2)
    n = len(gas)
    for start in range(n):
        tank = 0
        for k in range(n):
            i = (start + k) % n
            tank += gas[i] - cost[i]
            if tank < 0:
                break
        if tank >= 0:              # made the full loop
            return start
    return -1

def fast(gas, cost):               # greedy: one pass, O(N)
    if sum(gas) < sum(cost):
        return -1                  # not enough fuel in total
    start = tank = 0
    for i in range(len(gas)):
        tank += gas[i] - cost[i]
        if tank < 0:               # every start up to i fails, so try i + 1
            start = i + 1
            tank = 0
    return start

tests = [([1, 2, 3, 4, 5], [3, 4, 5, 1, 2]), ([2, 3, 4], [3, 4, 3]), ([5, 1, 2, 3, 4], [4, 4, 1, 5, 1])]
for gas, cost in tests:
    print(slow(gas, cost), fast(gas, cost))  # -> 3 3, then -1 -1, then 4 4
